          empty.textContent = state.emptyText || (state.selectFiles ? 'この階層にファイル・フォルダはありません。' : 'この階層にフォルダはありません。');
          empty.style.cssText = `padding:3px 8px 3px ${26 + (depth + 1) * 16}px;font-size:11px;color:var(--fg2);`;
