  const btnRight = btnRect.right / zoom;
  const btnTop = btnRect.top / zoom;
  const btnBottom = btnRect.bottom / zoom;
  // ボタンの左横、上端揃え。狭い画面ではボタンの上へ逃がしてボタンを隠さない。
  let x = btnLeft - toolbarWidth - 8;
  let y = btnTop;
