    const endDate = rawEnd ? new Date(rawEnd) : new Date(startDate.getTime() + minutes * 60000);
    if (!Number.isFinite(endDate.getTime()) || endDate <= startDate) throw _pmCloudError(400, '終了日時は開始日時より後にしてください');
