    handle.addEventListener('pointerdown', (e) => startColResize(e, th, domColIndex, p));
    handle.addEventListener('click', (e) => { e.stopPropagation(); });
    handle.addEventListener('dblclick', (e) => { e.stopPropagation(); });
    th.appendChild(handle);

