  const message = 'シートを読み込めませんでした: ' + (error?.message || error || '不明なエラー');
  const safeMessage = typeof esc === 'function'
    ? esc(message)
    : String(message).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
