        const valText = activeCell.querySelector('.value-text');
        if (valText) {
          valText.click();
          return;
        }
        const entityName = dataRows[rowIdx]?.querySelector('.entity-name-label')?.textContent;
        const propName = thAll[colIdx]?.dataset?.prop;
